-- Remove accounts generated by the automated test suite (*@example.com) and everything they own.
-- Real accounts and their bots/projects are untouched. Take a pg_dump first.
BEGIN;

CREATE TEMP TABLE del_users AS
    SELECT id FROM users WHERE email LIKE '%@example.com';
CREATE TEMP TABLE del_projects AS
    SELECT id FROM projects WHERE user_id IN (SELECT id FROM del_users);
CREATE TEMP TABLE del_bots AS
    SELECT id FROM bots WHERE project_id IN (SELECT id FROM del_projects);

DELETE FROM messages WHERE conversation_id IN (
    SELECT id FROM conversations WHERE bot_id IN (SELECT id FROM del_bots)
);
DELETE FROM conversations WHERE bot_id IN (SELECT id FROM del_bots);
DELETE FROM knowledge_chunks WHERE bot_id IN (SELECT id FROM del_bots);
DELETE FROM knowledge_sources WHERE bot_id IN (SELECT id FROM del_bots);
DELETE FROM bots WHERE id IN (SELECT id FROM del_bots);
DELETE FROM projects WHERE id IN (SELECT id FROM del_projects);
DELETE FROM users WHERE id IN (SELECT id FROM del_users);

COMMIT;
